import{_ as n,o as a,c as r,a3 as t}from"./chunks/framework.B9qR_F1m.js";const i="/bilder/flights-beladung.jpg",c=JSON.parse('{"title":"Beladung","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/beladung.md","filePath":"bereiche/beladung.md"}'),l={name:"bereiche/beladung.md"};function o(s,e,d,g,u,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="beladung" tabindex="-1">Beladung <a class="header-anchor" href="#beladung" aria-label="Permalink to &quot;Beladung&quot;">​</a></h1><p>Waffen, Pods und Tanks pro Station – ohne Mission Editor. Shardwing kennt die Stationen und erlaubten Stores von <strong>F-16C</strong> und <strong>F/A-18C</strong> aus den DCS-Daten und schreibt die Beladung beim Speichern in die .miz.</p><p><img src="'+i+'" alt="Reiter Beladung mit Stationsleiste" loading="lazy"></p><h2 id="die-stationsleiste" tabindex="-1">Die Stationsleiste <a class="header-anchor" href="#die-stationsleiste" aria-label="Permalink to &quot;Die Stationsleiste&quot;">​</a></h2><p>Jede Station ist eine Kachel – von links (Station 1) nach rechts. Eine Zeile darüber fasst die Beladung zusammen, z. B. <em>3×120C 9X · 2×AGM-65K 2×CBU-87 · HTS ATP · 300</em>.</p><p>Klick eine Station an, um sie zu belegen:</p><ul><li><strong>Suchen</strong>, z. B. „GBU-12“, oder nach Gruppen stöbern: Luft-Luft-Flugkörper, Lenkflugkörper, Bomben, Übungsbomben, Ziel- und Sensorpods, Tanks …</li><li>Angeboten wird nur, was DCS an dieser Station erlaubt.</li><li><strong>Leer</strong> lässt den Pylon dran; <strong>Pylon abbauen</strong> nimmt ihn ganz weg (weniger Widerstand und Gewicht).</li></ul><p><strong>Symmetrisch</strong> (Haken oben) belegt die gegenüberliegende Station gleich mit – Station 3 und 7 bei der F-16.</p><h2 id="fuel-chaff-flare-gun" tabindex="-1">Fuel, Chaff, Flare, Gun <a class="header-anchor" href="#fuel-chaff-flare-gun" aria-label="Permalink to &quot;Fuel, Chaff, Flare, Gun&quot;">​</a></h2><p>Unter der Leiste: <strong>Fuel</strong> in Prozent (mit der internen Menge in lbs daneben), Anzahl <strong>Chaff</strong> und <strong>Flare</strong>, <strong>Gun</strong> in Prozent.</p><h2 id="pro-flugzeug" tabindex="-1">Pro Flugzeug <a class="header-anchor" href="#pro-flugzeug" aria-label="Permalink to &quot;Pro Flugzeug&quot;">​</a></h2><p>Hat der Flight mehrere Flugzeuge, bekommt jedes eine eigene Leiste. So kann der Lead einen Pod tragen und der Wingman nicht.</p><h2 id="vorlagen" tabindex="-1">Vorlagen <a class="header-anchor" href="#vorlagen" aria-label="Permalink to &quot;Vorlagen&quot;">​</a></h2><ul><li><strong>Beladung übernehmen …</strong> – von einem anderen Flight der Mission, aus einer eigenen Vorlage oder <strong>Clean (alles leer)</strong>.</li><li><strong>Als Vorlage speichern</strong> – unter einem Namen wie „SEAD“; die Vorlage steht dir danach in jeder Mission für diesen Flugzeugtyp zur Verfügung (gespeichert auf deinem Rechner).</li></ul><h2 id="freigabe-fur-piloten" tabindex="-1">Freigabe für Piloten <a class="header-anchor" href="#freigabe-fur-piloten" aria-label="Permalink to &quot;Freigabe für Piloten&quot;">​</a></h2><p>Ganz unten legst du fest, was ein Flight Lead beim gemeinsamen Planen wählen darf: <strong>alles, was DCS erlaubt</strong>, oder <strong>nur freigegebene Waffen</strong>. So bleiben z. B. die JDAMs beim Strike-Flight. (<a href="/gemeinsam/rollen">Rollen und Freigaben</a>)</p><div class="info custom-block"><p class="custom-block-title">Was beim Speichern passiert</p><p>Shardwing ändert nur die Stationen, die du angefasst hast. Einstellungen unveränderter Stationen (z. B. Zünder) bleiben erhalten.</p></div>',17)])])}const f=n(l,[["render",o]]);export{c as __pageData,f as default};
